import io.github.vmzakharov.ecdataframe.dataframe.DataFrame;
import io.github.vmzakharov.ecdataframe.dsl.value.Value;
import io.github.vmzakharov.ecdataframe.dsl.value.ValueType;
import org.eclipse.collections.api.list.primitive.MutableBooleanList;
import org.eclipse.collections.impl.factory.primitive.BooleanLists;
import org.eclipse.collections.impl.factory.Lists;
import org.eclipse.collections.impl.list.mutable.FastList;
import org.junit.Assert;
import org.junit.Test;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.Arrays;

public class DataFrameTest {

    @Test
    public void DataFrameCreationTest() {
        DataFrame dataFrame = new DataFrame("TestName");
        Assert.assertEquals("TestName", dataFrame.getName());
    }

    @Test
    public void addRowTest() {
        DataFrame dataFrame = new DataFrame("TestName");
        dataFrame.addStringColumn("Column1");
        dataFrame.addRow(Arrays.asList(Value.asString("Test")));
        Assert.assertEquals("Test", dataFrame.getValue("Column1", 0).getString());
    }

    @Test
    public void rowCountTest() {
        DataFrame dataFrame = new DataFrame("TestName");
        dataFrame.addStringColumn("Column1");
        dataFrame.addRow(Arrays.asList(Value.asString("Test1")));
        dataFrame.addRow(Arrays.asList(Value.asString("Test2")));
        Assert.assertEquals(2, dataFrame.rowCount());
    }

    @Test
    public void addBooleanColumnTest() {
        DataFrame dataFrame = new DataFrame("TestName");
        dataFrame.addBooleanColumn("testColumn", Lists.mutable.with(true, false, true));
        Assert.assertEquals(2, dataFrame.selectBy("testColumn").rowCount());
    }

    @Test
    public void addDateColumnTest() {
        DataFrame dataFrame = new DataFrame("TestName");
        dataFrame.addDateColumn("testColumn", Lists.mutable.with(LocalDate.now(), LocalDate.of(2018, 10, 10)));
        Assert.assertEquals(LocalDate.now(), dataFrame.getDate("testColumn", 0));
    }

    @Test
    public void distinctTest() {
        DataFrame dataFrame = new DataFrame("TestName");
        dataFrame.addStringColumn("Column1");
        dataFrame.addRow(Arrays.asList(Value.asString("Test")));
        dataFrame.addRow(Arrays.asList(Value.asString("Test")));
        Assert.assertEquals(1, dataFrame.distinct().rowCount());
    }

    @Test
    public void evaluateExpressionTest() {
        DataFrame dataFrame = new DataFrame("TestName");
        dataFrame.addLongColumn("Column1", Lists.mutable.with(100l, 200l));
        dataFrame.addLongColumn("Column2", Lists.mutable.with(10l, 20l));
        dataFrame.addColumn("Sum", ValueType.LONG, "Column1 + Column2");
        Assert.assertEquals(110l, dataFrame.getLong("Sum", 0));
        Assert.assertEquals(220l, dataFrame.getLong("Sum", 1));
    }

    @Test
    public void joinTest() {
        DataFrame dataFrame1 = new DataFrame("TestName1");
        dataFrame1.addStringColumn("Column1");
        dataFrame1.addLongColumn("Column2", Lists.mutable.with(100l, 200l));

        DataFrame dataFrame2 = new DataFrame("TestName2");
        dataFrame2.addStringColumn("Column1");
        dataFrame2.addDoubleColumn("Column3", Lists.mutable.with(10.5, 5.2));

        DataFrame joinedDataFrame = dataFrame1.join(dataFrame2, "Column1", "Column1");

        Assert.assertEquals(4, joinedDataFrame.columnCount());
        Assert.assertEquals(100l, joinedDataFrame.getLong("Column2", 0));
        Assert.assertEquals(10.5, joinedDataFrame.getDouble("Column3", 0), 0.01);
    }

    @Test
    public void isEmptyTest() {
        DataFrame dataFrame = new DataFrame("TestName");
        Assertions.assertTrue(dataFrame.isEmpty());
    }

    @Test
    public void isNotEmptyTest() {
        DataFrame dataFrame = new DataFrame("TestName");
        dataFrame.addStringColumn("Column1");
        dataFrame.addRow(Arrays.asList(Value.asString("Test")));
        Assertions.assertTrue(dataFrame.isNotEmpty());
    }
}
